export class ListNode {
  val: number;
  next: ListNode | null;
  constructor(val = 0, next: ListNode | null = null) {
    this.val = val;
    this.next = next;
  }
}

export function hasCycle(head: ListNode | null): boolean {
  const visited = new Set<ListNode>();
  let curr = head;
  while (curr) {
    if (visited.has(curr)) {
      return true;
    }
    visited.add(curr);
    curr = curr.next;
  }
  return false;
}
